-------------------------------------------------------------------------------
-- Migration: replace sequence-backed id columns with IDENTITY columns.
-- For every changed column:
--   1. the nextval() default is removed and the sequence is dropped
--   2. the column is converted to GENERATED BY DEFAULT AS IDENTITY
--   3. the identity start value is set to MAX(id) + 1
-- The whole migration runs in a single transaction.
-------------------------------------------------------------------------------
BEGIN;

-------------------------------------------------------------------------------
-- 1. Drop defaults and sequences
ALTER TABLE topology.service ALTER COLUMN id DROP DEFAULT;
DROP SEQUENCE IF EXISTS topology.service_id_seq;
ALTER TABLE topology.volatile_instance ALTER COLUMN id DROP DEFAULT;
DROP SEQUENCE IF EXISTS topology.volatile_instance_id_seq;

ALTER TABLE common.tag ALTER COLUMN id DROP DEFAULT;
DROP SEQUENCE IF EXISTS common.tag_id_seq;
ALTER TABLE common.notification ALTER COLUMN id DROP DEFAULT;
DROP SEQUENCE IF EXISTS common.notification_id_seq;
ALTER TABLE common.visibility ALTER COLUMN id DROP DEFAULT;
DROP SEQUENCE IF EXISTS common.visibility_id_seq;
ALTER TABLE common.audit ALTER COLUMN id DROP DEFAULT;
DROP SEQUENCE IF EXISTS common.audit_id_seq;

ALTER TABLE usr.grp ALTER COLUMN id DROP DEFAULT;
DROP SEQUENCE IF EXISTS usr.group_id_seq;
ALTER TABLE usr.user_status ALTER COLUMN id DROP DEFAULT;
DROP SEQUENCE IF EXISTS usr.user_status_id_seq;

ALTER TABLE product.data_format ALTER COLUMN id DROP DEFAULT;
DROP SEQUENCE IF EXISTS product.data_format_id_seq;
ALTER TABLE product.pixel_type ALTER COLUMN id DROP DEFAULT;
DROP SEQUENCE IF EXISTS product.pixel_type_id_seq;
ALTER TABLE product.sensor_type ALTER COLUMN id DROP DEFAULT;
DROP SEQUENCE IF EXISTS product.sensor_type_id_seq;
ALTER TABLE product.orbit_direction ALTER COLUMN id DROP DEFAULT;
DROP SEQUENCE IF EXISTS product.orbit_direction_id_seq;
ALTER TABLE product.polarisation_mode ALTER COLUMN id DROP DEFAULT;
DROP SEQUENCE IF EXISTS product.polarisation_mode_id_seq;
ALTER TABLE product.polarisation_channel ALTER COLUMN id DROP DEFAULT;
DROP SEQUENCE IF EXISTS product.polarisation_channel_id_seq;
ALTER TABLE product.product_status ALTER COLUMN id DROP DEFAULT;
DROP SEQUENCE IF EXISTS product.product_status_id_seq;
ALTER TABLE product.data_type ALTER COLUMN id DROP DEFAULT;
DROP SEQUENCE IF EXISTS product.data_type_id_seq;
ALTER TABLE product.naming_rule ALTER COLUMN id DROP DEFAULT;
DROP SEQUENCE IF EXISTS product.naming_rule_id_seq;
ALTER TABLE product.data_sources_index ALTER COLUMN id DROP DEFAULT;
DROP SEQUENCE IF EXISTS product.data_sources_index_id_seq;

ALTER TABLE component.component_category ALTER COLUMN id DROP DEFAULT;
DROP SEQUENCE IF EXISTS component.component_category_id_seq;
ALTER TABLE component.parameter_type ALTER COLUMN id DROP DEFAULT;
DROP SEQUENCE IF EXISTS component.parameter_type_id_seq;
ALTER TABLE component.component_visibility ALTER COLUMN id DROP DEFAULT;
DROP SEQUENCE IF EXISTS component.component_visibility_id_seq;
ALTER TABLE component.template_type ALTER COLUMN id DROP DEFAULT;
DROP SEQUENCE IF EXISTS component.template_type_id_seq;
ALTER TABLE component.fetch_mode ALTER COLUMN id DROP DEFAULT;
DROP SEQUENCE IF EXISTS component.fetch_mode_id_seq;
ALTER TABLE component.container_type ALTER COLUMN id DROP DEFAULT;
DROP SEQUENCE IF EXISTS component.container_type_id_seq;
ALTER TABLE component.component_dry_run_metrics ALTER COLUMN id DROP DEFAULT;
DROP SEQUENCE IF EXISTS component.component_dry_run_metrics_id_seq;
-- varchar ids: the sequences are dropped, but the columns cannot become IDENTITY
ALTER TABLE component.processing_component ALTER COLUMN id DROP DEFAULT;
DROP SEQUENCE IF EXISTS component.processing_component_id_seq;
ALTER TABLE component.condition_component ALTER COLUMN id DROP DEFAULT;
DROP SEQUENCE IF EXISTS component.condition_component_id_seq;

ALTER TABLE workflow.status ALTER COLUMN id DROP DEFAULT;
DROP SEQUENCE IF EXISTS workflow.graph_status_id_seq;
ALTER TABLE workflow.graph ALTER COLUMN id DROP DEFAULT;
DROP SEQUENCE IF EXISTS workflow.workflow_graph_id_seq;
ALTER TABLE workflow.graph_node ALTER COLUMN id DROP DEFAULT;
DROP SEQUENCE IF EXISTS workflow.graph_node_id_seq;
ALTER TABLE workflow.query ALTER COLUMN id DROP DEFAULT;
DROP SEQUENCE IF EXISTS workflow.query_id_seq;
ALTER TABLE workflow.query_parameter ALTER COLUMN id DROP DEFAULT;
DROP SEQUENCE IF EXISTS workflow.query_parameter_id_seq;

ALTER TABLE execution.status ALTER COLUMN id DROP DEFAULT;
DROP SEQUENCE IF EXISTS execution.execution_status_id_seq;
ALTER TABLE execution.job ALTER COLUMN id DROP DEFAULT;
DROP SEQUENCE IF EXISTS execution.job_id_seq;
ALTER TABLE execution.task ALTER COLUMN id DROP DEFAULT;
DROP SEQUENCE IF EXISTS execution.task_id_seq;
ALTER TABLE execution.user_data_source_connection ALTER COLUMN id DROP DEFAULT;
DROP SEQUENCE IF EXISTS execution.user_data_source_connection_id_seq;
ALTER TABLE execution.resource_usage ALTER COLUMN id DROP DEFAULT;
DROP SEQUENCE IF EXISTS execution.resource_usage_id_seq;
ALTER TABLE execution.resource_usage_report ALTER COLUMN id DROP DEFAULT;
DROP SEQUENCE IF EXISTS execution.resource_usage_report_id_seq;

ALTER TABLE subscription.workflow ALTER COLUMN id DROP DEFAULT;
DROP SEQUENCE IF EXISTS subscription.workflow_id_seq;
ALTER TABLE subscription.dataset ALTER COLUMN id DROP DEFAULT;
DROP SEQUENCE IF EXISTS subscription.dataset_id_seq;
ALTER TABLE subscription.resource_subscription ALTER COLUMN id DROP DEFAULT;
DROP SEQUENCE IF EXISTS subscription.resource_subscription_id_seq;
ALTER TABLE subscription.external_resource_subscription ALTER COLUMN id DROP DEFAULT;
DROP SEQUENCE IF EXISTS subscription.external_resource_subscription_id_seq;

-------------------------------------------------------------------------------
-- 2. Convert the columns to IDENTITY
ALTER TABLE topology.service ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY;
ALTER TABLE topology.volatile_instance ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY;

ALTER TABLE common.tag ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY;
ALTER TABLE common.notification ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY;
ALTER TABLE common.visibility ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY;
ALTER TABLE common.audit ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY;

ALTER TABLE usr.grp ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY;
ALTER TABLE usr.user_status ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY;

ALTER TABLE product.data_format ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY;
ALTER TABLE product.pixel_type ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY;
ALTER TABLE product.sensor_type ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY;
ALTER TABLE product.orbit_direction ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY;
ALTER TABLE product.polarisation_mode ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY;
ALTER TABLE product.polarisation_channel ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY;
ALTER TABLE product.product_status ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY;
ALTER TABLE product.data_type ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY;
ALTER TABLE product.naming_rule ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY;
ALTER TABLE product.data_sources_index ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY;

ALTER TABLE component.component_category ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY;
ALTER TABLE component.parameter_type ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY;
ALTER TABLE component.component_visibility ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY;
ALTER TABLE component.template_type ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY;
ALTER TABLE component.fetch_mode ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY;
ALTER TABLE component.container_type ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY;
ALTER TABLE component.component_dry_run_metrics ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY;

ALTER TABLE workflow.status ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY;
ALTER TABLE workflow.graph ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY;
ALTER TABLE workflow.graph_node ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY;
ALTER TABLE workflow.query ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY;
ALTER TABLE workflow.query_parameter ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY;

ALTER TABLE execution.status ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (MINVALUE 0 START WITH 0);
ALTER TABLE execution.job ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY;
ALTER TABLE execution.task ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY;
ALTER TABLE execution.user_data_source_connection ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY;
ALTER TABLE execution.resource_usage ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY;
ALTER TABLE execution.resource_usage_report ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY;

ALTER TABLE subscription.workflow ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY;
ALTER TABLE subscription.dataset ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY;
ALTER TABLE subscription.resource_subscription ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY;
ALTER TABLE subscription.external_resource_subscription ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY;

-------------------------------------------------------------------------------
-- 3. Set the IDENTITY start value to MAX(id) + 1
DO $$
DECLARE
    t record;
    next_id bigint;
BEGIN
    FOR t IN SELECT * FROM (VALUES
        ('topology', 'service'),
        ('topology', 'volatile_instance'),
        ('common', 'tag'),
        ('common', 'notification'),
        ('common', 'visibility'),
        ('common', 'audit'),
        ('usr', 'grp'),
        ('usr', 'user_status'),
        ('product', 'data_format'),
        ('product', 'pixel_type'),
        ('product', 'sensor_type'),
        ('product', 'orbit_direction'),
        ('product', 'polarisation_mode'),
        ('product', 'polarisation_channel'),
        ('product', 'product_status'),
        ('product', 'data_type'),
        ('product', 'naming_rule'),
        ('product', 'data_sources_index'),
        ('component', 'component_category'),
        ('component', 'parameter_type'),
        ('component', 'component_visibility'),
        ('component', 'template_type'),
        ('component', 'fetch_mode'),
        ('component', 'container_type'),
        ('component', 'component_dry_run_metrics'),
        ('workflow', 'status'),
        ('workflow', 'graph'),
        ('workflow', 'graph_node'),
        ('workflow', 'query'),
        ('workflow', 'query_parameter'),
        ('execution', 'status'),
        ('execution', 'job'),
        ('execution', 'task'),
        ('execution', 'user_data_source_connection'),
        ('execution', 'resource_usage'),
        ('execution', 'resource_usage_report'),
        ('subscription', 'workflow'),
        ('subscription', 'dataset'),
        ('subscription', 'resource_subscription'),
        ('subscription', 'external_resource_subscription')
    ) AS v(schema_name, table_name)
    LOOP
        EXECUTE format('SELECT COALESCE(MAX(id), 0) + 1 FROM %I.%I', t.schema_name, t.table_name) INTO next_id;
        EXECUTE format('ALTER TABLE %I.%I ALTER COLUMN id SET START WITH %s RESTART WITH %s',
                       t.schema_name, t.table_name, next_id, next_id);
    END LOOP;
END $$;

COMMIT;
